data: {"id": "06048f4c-75e0-40f7-a784-72ebe584626e:directions", "type": "directions", "options": [{"id": "direction-1", "name": "窗边木桌的松早上", "scene": "街角咖啡店靠窗木桌，上午柔和侧光，桌上一杯拿铁、一本书，背景是浅木色墙和干花，不杂乱", "mood": "安静、松弛、像随手翻了两页书的日常", "palette": ["米白", "浅蓝", "浅木色", "燕麦色"], "why": "米白亚麻＋浅蓝水洗是这方向最松的一组配色，自然光把亚麻的纹理和牛仔的水洗层次都带出来；窗边侧光正好拍到袖口翻边和胸袋的明暗，符合至少一张看清袖口的需求。脚上配燕麦色帆布平底鞋，不破坏整体柔和。", "sample_title": "秋日咖啡店，米白配浅蓝就够松", "recommended": true, "styling": "米白亚麻衬衫自然放摆、袖口随手翻一道，塞一点前摆进浅蓝直筒牛仔裤，踩燕麦色帆布平底鞋，配帆布小托特包，米白和浅蓝为主，浅木色作背景。", "preview_status": "queued", "preview_url": null}, {"id": "direction-2", "name": "门口气氛的降温日常", "scene": "咖啡店门口矮台阶与街边绿植旁，午后偏暖阳光，光线从侧后方勾出衣领轮廓，背景是浅灰墙和一小片绿", "mood": "有点随性、带秋凉、像出门买咖啡的两分钟", "palette": ["米白", "浅蓝", "墨绿", "暖棕"], "why": "户外暖光让米白衬衫比室内更透亮，浅蓝牛仔在灰墙前更清爽；镜头能拍出裤型的完整落地线条。墨绿植色和暖棕配件只做点缀，保持通勤感又不呆。", "sample_title": "咖啡店门口那两分钟，刚好凉", "recommended": false, "styling": "米白亚麻衬衫前襟松两颗纽扣、下摆全放出来，浅蓝高腰直筒牛仔裤，脚上暖棕色平底乐福鞋，挎一只墨绿小斜挎包，配银色细圈耳环。", "preview_status": "queued", "preview_url": null}, {"id": "direction-3", "name": "吧台与木质长凳", "scene": "咖啡店吧台一角的长木凳，室内暖光加一点窗边漫射，镜头从桌面高度平视，背景是咖啡机与陶瓷杯架", "mood": "柔和、生活气、像坐一会儿再走", "palette": ["米白", "浅蓝", "奶油白", "浅灰"], "why": "平视高度更适合讲面料——亚麻的门襟、纽扣和胸袋一览无余，也能看清袖口折边的细节；奶油白与浅灰室内色让米白衬衫不显脏，浅蓝牛仔仍是清透的那块。整体偏通勤，站起来就能进办公室。", "sample_title": "吧台坐一会儿，米白亚麻很安静", "recommended": false, "styling": "米白亚麻衬衫袖口翻一道、扣到第三颗，前摆半塞进浅蓝直筒牛仔裤，系一条细浅灰皮带，脚上奶油白平底穆勒鞋，手上一只细银戒指。", "preview_status": "queued", "preview_url": null}], "regenerate_estimate_cny": 1.5, "regenerate_estimate_points": 15.0}

